  const hitIds=new Set(hits.map(x=>x.walk.uid));for(const v of related)if(v.walkUid&&!hitIds.has(v.walkUid))await remove('visits',v.id);
  for(const {walk,point} of hits)if(!byWalk.has(walk.uid))await put('visits',{uid:uid(),landmarkUid:landmark.uid,walkUid:walk.uid,date:Number(point?.t||walk.date),updatedAt:now(),radiusCalculated:true});
