function v9RecalculatePartnerVisits(landmark){if(!partnerSnapshot)return;const other=(partnerSnapshot.visits||[]).filter(v=>v.landmarkUid!==landmark.uid||!v.walkUid),added=[];for(const w of partnerSnapshot.walks||[]){let closest=null,best=Infinity;for(const p of w.points||[]){const d=dist(p,landmark);if(d<best){best=d;closest=p}}if(best<=Number(landmark.radius||50))added.push({uid:uid(),landmarkUid:landmark.uid,walkUid:w.uid,date:Number(closest?.t||w.date),updatedAt:now(),radiusCalculated:true})}partnerSnapshot.visits=[...other,...added]}

function v9StatAdd(group,key,value,weight=1){if(!Number.isFinite(value)||value<=0)return;const s=group[key]||{sum:0,sumSq:0,count:0};s.sum+=value*weight;s.sumSq+=value*value*weight;s.count+=weight;group[key]=s}
function v9StatMean(s){return s?.count?s.sum/s.count:null}
function v9StatCv(s){if(!s?.count)return Infinity;const mean=s.sum/s.count,variance=Math.max(0,s.sumSq/s.count-mean*mean);return mean?Math.sqrt(variance)/mean:Infinity}
