  const addEdge=(a,b,d,sec,grade,tb,source,observed,weight=1)=>{if(a.key===b.key)return null;let e=a.edges.get(b.key);if(!e){e={to:b.key,distanceSum:0,secondsSum:0,samples:0,observedCount:0,gradeSum:0,gradeCount:0,sources:new Set(),timeStats:{},estimated:false};a.edges.set(b.key,e)}e.distanceSum+=d*weight;e.secondsSum+=sec*weight;e.samples+=weight;if(observed)e.observedCount+=weight;if(Number.isFinite(grade)){e.gradeSum+=grade*weight;e.gradeCount+=weight}e.sources.add(source);v9StatAdd(e.timeStats,tb,d/sec,weight);return e};
